// caller: active.get().thenAccept(this::handle);  // no blocking rendezvous

private final ExecutorService perTask = Executors.newVirtualThreadPerTaskExecutor();
private final Semaphore one = new Semaphore(1);          // serialize per object

Future<?> put(Message m) {
    return perTask.submit(() -> {
        one.acquire();
        try { servant.put_i(m); } finally { one.release(); }
        return null;
    });
}
